const ReadAloudButton=({text,color,t})=>{
  const[speaking,setSpeaking]=useState(false);
  const[supported,setSupported]=useState(false);
  useEffect(()=>{if(typeof window!=="undefined"&&"speechSynthesis" in window)setSupported(true);},[]);
  useEffect(()=>()=>{if(typeof window!=="undefined"&&"speechSynthesis" in window)window.speechSynthesis.cancel();},[]);
  if(!supported) return null;
  const toggle=()=>{
    if(speaking){window.speechSynthesis.cancel();setSpeaking(false);return;}
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(text);
    u.rate=1.0;u.pitch=1.0;
    u.onend=()=>setSpeaking(false);
    u.onerror=()=>setSpeaking(false);
    window.speechSynthesis.speak(u);
    setSpeaking(true);
  };
  return <button onClick={toggle} aria-label={speaking?"Stop reading aloud":"Read aloud"} style={{display:"flex",alignItems:"center",gap:5,background:"none",border:`1px solid ${color}55`,borderRadius:8,padding:"5px 9px",cursor:"pointer",color,fontSize:10.5,fontWeight:700,fontFamily:FONT,letterSpacing:".02em",flexShrink:0}}>
    {speaking?"⏹ Stop":"🔊 Listen"}
  </button>;
};
const Skeleton=({t,height=60})=><div style={{background:t.isDark?"rgba(255,255,255,.04)":"rgba(0,0,0,.04)",borderRadius:10,height,marginBottom:10,animation:"shimmer 1.5s infinite"}}/>;
function useCountUp(target,start,duration=1400){
  const[display,setDisplay]=useState(target);
  const startedRef=useRef(false);
  useEffect(()=>{
    if(startedRef.current||isNaN(target)||isNaN(start))return;
    startedRef.current=true;
    if(start>=target){setDisplay(target);return;}
    let raf;const t0=performance.now();
    function tick(now){
      const p=Math.min((now-t0)/duration,1);
      const eased=1-Math.pow(1-p,3);
      setDisplay(Math.round(start+(target-start)*eased));
      if(p<1)raf=requestAnimationFrame(tick);
    }
    raf=requestAnimationFrame(tick);
    return()=>raf&&cancelAnimationFrame(raf);
  },[]);
  return display;
}
function CountUpTotal({total,delta,duration=1400,style}){
  const target=parseInt(String(total).replace(/[^0-9]/g,""),10);
  if(isNaN(target))return <span style={style}>{total}</span>;
  const d=delta&&delta!=="—"?Math.abs(parseInt(String(delta).replace(/[^0-9]/g,""),10)||0):0;
  const start=Math.max(0,target-d);
  const display=useCountUp(target,start,duration);
  const prefix=String(total).trim().startsWith("+")?"+":"";
  const suffix=(String(total).match(/[^0-9,]+$/)||[""])[0];
  return <span style={style}>{prefix}{display.toLocaleString()}{suffix}</span>;
}
function TrendTooltip({active,payload,label,t,color,unit}){
  if(!active||!payload?.length)return null;
  const v=payload[0]?.value;
  return <div style={{background:t.isDark?"#101d30":"#fff",border:`1px solid ${color}66`,borderRadius:8,padding:"7px 11px",fontSize:11,boxShadow:"0 4px 16px rgba(0,0,0,.28)"}}>
    <div style={{color:t.sub,fontSize:10,marginBottom:2}}>{label}</div>
    <div style={{color,fontWeight:800,fontSize:14,fontVariantNumeric:"tabular-nums"}}>{typeof v==="number"?v.toLocaleString():v}</div>
    <div style={{color:t.sub,fontSize:9.5}}>{unit}</div>
  </div>;
}

function useCountdown(target){const[text,setText]=useState("");useEffect(()=>{const tick=()=>{const ms=target.getTime()-Date.now();if(ms<=0){setText("ELAPSED");return;}const d=Math.floor(ms/86400000),h=Math.floor((ms%86400000)/3600000),m=Math.floor((ms%3600000)/60000);setText(`D-${d} · ${h}h ${m}m`);};tick();const id=setInterval(tick,60000);return()=>clearInterval(id);},[target]);return text;}

