function WorldMap({t,conflicts,onSelect,selectedId}){const ocean=t.isDark?"#060d1a":"#dae4f0",land=t.isDark?"#0e1e35":"#b8cce0",border=t.isDark?"#152a46":"#8aaec8";return <div style={{background:ocean,borderRadius:14,overflow:"hidden",border:`1px solid ${t.border}`,marginBottom:16}}><div style={{padding:"8px 14px 4px",display:"flex",alignItems:"center",gap:6}}><span style={{fontSize:10,fontWeight:700,color:t.sub,textTransform:"uppercase",letterSpacing:".08em"}}>🌍 Active Conflict Theaters</span><span style={{fontSize:10,color:t.sub,marginLeft:"auto"}}>tap pin to navigate</span></div><svg viewBox="0 0 800 380" width="100%" style={{display:"block"}}><rect width={800} height={380} fill={ocean}/><path d={WORLD_LAND_PATH} fill={land} stroke={border} strokeWidth="0.6"/>{conflicts.map(c=>{const pin=THEATER_COORDS[c.id];if(!pin)return null;const isSel=selectedId===c.id,r=isSel?11:8;const isVolatile=["ESCALATING","NEW CIVIL WAR","US INTERVENTION"].includes(c.status);return <g key={c.id} style={{cursor:"pointer"}} onClick={()=>onSelect(c.id)}><circle cx={pin.x} cy={pin.y} r={r+10} fill={c.statusColor} opacity={0.07}/>{isVolatile&&<circle cx={pin.x} cy={pin.y} r={r} fill="none" stroke={c.statusColor} strokeWidth={1.5} style={{transformOrigin:`${pin.x}px ${pin.y}px`,animation:"radarPing 1.8s ease-out infinite"}}/>}{isSel&&<circle cx={pin.x} cy={pin.y} r={r+18} fill="none" stroke={c.statusColor} strokeWidth={1} opacity={0.35} strokeDasharray="4,3"/>}<circle cx={pin.x} cy={pin.y} r={r} fill={c.statusColor} opacity={isSel?1:0.88}/><text textAnchor="middle" x={pin.x} y={pin.y+4} fontSize={isSel?10:8} fill="#fff" fontWeight="bold" style={{pointerEvents:"none"}}>{c.icon}</text><text textAnchor="middle" x={pin.x} y={pin.y+r+13} fontSize={8} fill={isSel?c.statusColor:t.isDark?"rgba(255,255,255,0.7)":"rgba(0,0,0,0.6)"} fontWeight={isSel?"bold":"normal"} style={{pointerEvents:"none"}}>{pin.label}</text></g>;})}</svg></div>;}

// ── Ukraine Frontline Map SVG ─────────────────────────────────────────────────────
const SECTORS=[{name:"Dnipropetrovsk",icon:"🟢",status:"ADVANCE",color:"#22c55e",detail:"Ukraine's rare good-news story this month: Zelensky announced Aug 13 the successful conclusion of a counteroffensive that recaptured 745 km\u00b2 (287 sq mi) of Ukrainian territory in the Dnipropetrovsk region this year, pushing Russia back over the regional borders into Donetsk and Zaporizhzhia and depriving it of nearly all the ground it had gained there since entering the region in June 2025. Zelensky and former commander-in-chief Oleksandr Syrskii, who planned the operation, said close to 10,000 Russian soldiers were killed in the process. It's one of the only sectors this year where Ukraine, not Russia, is the one advancing.",},{name:"Pokrovsk area",icon:"🔴",status:"CRITICAL",color:"#ef4444",detail:"Still the single hottest sector on the front alongside Huliaipole and Kostyantynivka, with Russian assault density consistently heaviest here through early August — Ukraine's General Staff logged 23 Russian attacks in the Pokrovsk sector alone on Aug 6, the heaviest of 170 engagements dashboard-wide that day. Russia claimed the city's capture earlier in the year but has been unable to fully consolidate or push meaningfully west of it since — the front here has stabilized into grinding, incremental fighting rather than a clean breakthrough. ISW assesses Russia's entire Spring-Summer 2026 offensive gained just 37.85 km² of Ukrainian territory in July — smaller than Manhattan — averaging 1.22 km²/day. Ukraine's AI-enabled drone interdiction (per CSIS) is a major reason Russian gains remain historically slow despite the pressure."},{name:"Kostyantynivka",icon:"🔴",status:"ACTIVE",color:"#ef4444",detail:"Remains contested and a recurring subject of disputed Russian capture claims that ISW and other OSINT trackers have repeatedly found unsupported by ground evidence — a pattern consistent with Kremlin information-operation timing around Western media cycles rather than confirmed battlefield change. ISW assesses Russian forces are now running a battlefield air interdiction campaign against Slovyansk and Kramatorsk — the northern tip of Donetsk Oblast's Fortress Belt — using drones, missiles and glide bombs against Ukrainian logistics, vehicles and railways. The objective mirrors the 2025 campaigns that preceded advances at Pokrovsk and Hulyaipole: isolate the defenders before assaulting the belt itself."},{name:"Kupyansk",icon:"🔴",status:"ACTIVE",color:"#ef4444",detail:"Russian infiltration pressure continues on the city's outskirts. Russian milbloggers have repeatedly posted likely AI-altered flag-raising footage as part of a cognitive-war effort to exaggerate the pace of advances — a recurring tactic across multiple sectors this year."},{name:"Zaporizhzhia",icon:"🟡",status:"MODERATE",color:"#eab308",detail:"Ukrainian forces have held or advanced within the Orikhiv/Prymorske area for much of 2026. Molniya AI-guided loitering munitions are now used en masse by Russian forces here — existing Ukrainian detectors reportedly remain only partially effective against them."},{name:"Kherson",icon:"🟡",status:"MODERATE",color:"#eab308",detail:"Ground activity remains limited. Ukraine continues intermediate-range strikes on Russian military/energy assets in occupied Kherson Oblast."},{name:"Crimea",icon:"⚡",status:"SIEGE",color:"#5b8ec8",detail:"State of emergency conditions persist — fuel and water shortages, civilian exodus, and rolling power cuts that have left occupied Feodosia without electricity since Jul 28. Russian 810th Naval Infantry Brigade elements run mobile fire groups against Ukrainian drones; a Russian milblogger has admitted refinery repairs are 'useless' against repeated strikes, including the Jul 28 hit near Ichki. Ukraine struck a Russian naval-drone storage and maintenance site near Chornomorske (Aug 1) and, on Aug 16, hit one of Russia's scarce S-300V4/Bastion coastal-defense systems — the Zircon/Oniks launch platform — plus a missile and artillery depot near Solone Ozero."}];
