function LossesTab({t}){const[sortBy,setSortBy]=useState("default");const chartData=CASUALTIES.map(c=>({d:c.date,kia:c.value}));const avg7d=Math.round(CASUALTIES.slice(-7).reduce((a,b)=>a+b.value,0)/7);const vals=chartData.map(d=>d.kia);const yMin=Math.floor(Math.min(...vals)/50)*50-50;const yMax=Math.ceil(Math.max(...vals)/50)*50+50;const sortedByTotal=useMemo(()=>[...LOSSES.ukraine].sort((a,b)=>(parseInt(b.total.replace(/[^0-9]/g,""))||0)-(parseInt(a.total.replace(/[^0-9]/g,""))||0)),[]);const displayLosses=sortBy==="total"?sortedByTotal:LOSSES.ukraine;
  const weeklyCas=(()=>{const out=[];for(let end=CASUALTIES.length;end-7>=0;end-=7){const s=CASUALTIES.slice(end-7,end);out.unshift({m:s[6].date,avg:Math.round(s.reduce((a,b)=>a+b.value,0)/7),total:s.reduce((a,b)=>a+b.value,0)});}return out;})();
  const wkDelta=weeklyCas.length>=2?weeklyCas[weeklyCas.length-1].avg-weeklyCas[weeklyCas.length-2].avg:0;
  const dailyCasFull=CASUALTIES.map(d=>({m:d.date,v:d.value}));
  const casMA=dailyCasFull.map((d,i)=>({...d,ma:i>=6?Math.round(dailyCasFull.slice(i-6,i+1).reduce((a,b)=>a+b.v,0)/7):null}));
  const costPerKm=HISTORICAL.ruTerritoryKm2.map((d,i)=>({m:d.m,v:Math.round(HISTORICAL.ruCasualtiesMonthly[i].v/Math.max(1,d.v))}));
  return <div><ST t={t}>📊 Daily Russian Casualties — Last 14 Days</ST><Card t={t} style={{padding:"14px 8px 8px"}}><div style={{height:180}}><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{top:0,right:4,left:-20,bottom:0}}><defs><linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#ef4444" stopOpacity={0.3}/><stop offset="95%" stopColor="#ef4444" stopOpacity={0}/></linearGradient></defs><XAxis dataKey="d" tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false}/><YAxis domain={[yMin,yMax]} tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false}/><Tooltip cursor={{stroke:"#ef4444",strokeWidth:1,strokeDasharray:"4 3",opacity:0.65}} content={<TrendTooltip t={t} color="#ef4444" unit="killed/wounded that day"/>}/><ReferenceLine y={avg7d} stroke="#fbbf24" strokeDasharray="4 2" strokeWidth={1.5}/><Area type="monotone" dataKey="kia" stroke="#ef4444" fill="url(#areaGrad)" strokeWidth={2} activeDot={{r:5,fill:"#ef4444",stroke:t.isDark?"#0b1420":"#fff",strokeWidth:2}}/></AreaChart></ResponsiveContainer></div><div style={{display:"flex",alignItems:"center",gap:6,padding:"4px 8px",fontSize:11,color:t.sub}}><span style={{width:18,height:2,background:"#fbbf24",display:"inline-block"}}/>7-day avg: ~{avg7d.toLocaleString()}/day</div></Card><div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginTop:14,marginBottom:6}}><ST t={t}>🇷🇺 Equipment Destroyed</ST><div style={{display:"flex",gap:4}}>{["default","total"].map(s=><button key={s} onClick={()=>setSortBy(s)} style={{padding:"3px 8px",fontSize:10,borderRadius:6,cursor:"pointer",fontFamily:FONT,fontWeight:600,background:sortBy===s?"#5b8ec8":"none",color:sortBy===s?"#fff":t.sub,border:`1px solid ${sortBy===s?"#5b8ec8":t.border}`}}>{s==="default"?"Default":"Sort by Total"}</button>)}</div></div><Card t={t}>{displayLosses.map((item,i)=><Row key={item.id} t={t} last={i===displayLosses.length-1}><span style={{fontSize:18,width:28,textAlign:"center",flexShrink:0}}>{item.icon}</span><div style={{flex:1}}><div style={{fontSize:13,fontWeight:600,color:t.text}}>{item.category}</div><div style={{fontSize:11,color:t.sub}}>{item.description}</div></div><div style={{textAlign:"right",flexShrink:0}}><div style={{fontSize:15,fontWeight:700,color:item.color??t.text,fontVariantNumeric:"tabular-nums"}}><CountUpTotal total={item.total} delta={item.todayChange} duration={1200}/></div><div style={{fontSize:11,fontWeight:500,color:item.todayChange==="—"?t.sub:"#22c55e"}}>{item.todayChange}</div></div></Row>)}</Card>
    <ST t={t}>📈 2026 Trends</ST>
    <TrendChart t={t} data={HISTORICAL.ruCasualtiesCumulative} color="#ef4444" label="Cumulative RU Casualties" unit="total killed/wounded" area desc="Crossed 1.4M in June, reached 1,447,620 by end of July. Not a flat rate — attrition has climbed steadily since February’s low, with July’s 42,860 a 2026 record and no sign of the rate easing." />
    <TrendChart t={t} data={ruMonthlyWithMTD()} color="#f97316" label="Monthly RU Casualty Rate" unit="killed/wounded per month" desc="July closed at 42,860 — Russia’s worst month of the war so far per Ukraine’s General Staff, up roughly a third from June’s 39,290. Every month from March onward has cost more than the last; February (26,090) remains the year’s low point. The final point is the current month accumulating in real time from the daily MoD reports, so it sits below the completed months until the month closes." />
    <div style={{height:150}}><ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={weeklyCas} margin={{top:4,right:8,left:-12,bottom:0}}>
          <XAxis dataKey="m" tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false}/>
          <YAxis domain={[0,Math.ceil(Math.max(...weeklyCas.map(d=>d.avg))/200)*200+200]} tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false} width={38}/>
          <Tooltip cursor={{fill:"#ef444422"}} content={<TrendTooltip t={t} color="#ef4444" unit="avg/day, 7-day window"/>}/>
          <Bar dataKey="avg" name="avg" fill="#ef4444" radius={[3,3,0,0]}/>
        </ComposedChart>
      </ResponsiveContainer></div>
    <div style={{fontSize:11,color:t.sub,lineHeight:1.5,padding:"2px 8px 14px"}}>Weekly RU personnel losses, avg/day — each bar a complete 7-day window ending on the date shown. Latest week runs {weeklyCas[weeklyCas.length-1].avg.toLocaleString()}/day ({weeklyCas[weeklyCas.length-1].total.toLocaleString()} total), {wkDelta===0?"flat versus":wkDelta>0?"up "+wkDelta.toLocaleString()+"/day on":"down "+Math.abs(wkDelta).toLocaleString()+"/day on"} the week before.</div>
    <TrendChart t={t} data={HISTORICAL.ruTerritoryKm2} color="#eab308" label="RU Territorial Gains" unit="km² captured per month" desc="Russian advance peaked in March (31km²), fell through June, then ticked back up in July to a new year-high ~38km², per ISW — but that uptick came the same month Russia suffered a record 42,860 casualties, the starkest attrition-vs-gain mismatch of the war so far." />
    <TrendChart t={t} data={costPerKm} color="#dc2626" label="Casualties per km² Gained" unit="RU killed/wounded per km² captured" area desc="Derived series: monthly casualties divided by territorial gain. The ratio bottomed at ~1,030 in March, then climbed sharply through Q2 as gains shrank while casualties rose, peaking at ~3,570 per km² in June. July reversed that spike — back down to ~1,130 per km² — not because the war got cheaper, but because territorial gains jumped back to a year-high (~38km²) alongside record casualties (42,860). Read alongside the raw casualty and territory charts above rather than in isolation." />
    <TrendChart t={t} data={HISTORICAL.refineryOffline} color="#22c55e" label="RU Refining Capacity Offline" unit="% of national capacity" area desc="From ~8% in January to 43% by July, per Ukraine's General Staff — the cumulative effect of the deep-strike campaign on Russia's fuel economy. Some independent trackers reported even steeper mid-to-late-July estimates; 43% is the more conservative, officially-sourced figure." />
    <ST t={t} color="#5b8ec8">🔗 Related</ST>
    <a href="/background/russian-casualties-ukraine" style={{display:"block",textDecoration:"none"}}><Card t={t} style={{borderLeft:"4px solid #5b8ec8"}}><div style={{padding:"11px 14px"}}><div style={{fontSize:11,fontWeight:800,letterSpacing:".08em",color:"#5b8ec8",textTransform:"uppercase",marginBottom:6}}>📖 Explainer</div><div style={{fontSize:13,fontWeight:700,color:t.text,marginBottom:6}}>Russian casualties in Ukraine: how the numbers are counted</div><div style={{fontSize:12,color:t.sub,lineHeight:1.6}}>Methodology, sourcing, and how General Staff figures compare to independent estimates. →</div></div></Card></a>
  </div>;}

function FrontlineTab({t}){const[sel,setSel]=useState(null);const selSec=sel?SECTORS.find(s=>s.name===sel):null;return <div><ST t={t}>🗺️ Situation Map — {REPORT_NOW.toLocaleDateString("en-GB",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"})}</ST><div style={{fontSize:11,color:t.sub,textAlign:"center",marginBottom:6}}>Tap a sector pin for detail · Dashed red = contact line</div><FMap t={t} sel={sel} setSel={setSel}/>{selSec?<div style={{margin:"8px 0 12px",background:`${selSec.color}12`,border:`1.5px solid ${selSec.color}55`,borderRadius:10,padding:"12px 14px"}}><div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}><span style={{fontSize:18}}>{selSec.icon}</span><span style={{fontSize:14,fontWeight:800,color:t.text,flex:1}}>{selSec.name}</span><Pill label={selSec.status} color={selSec.color}/><button onClick={()=>setSel(null)} aria-label="Close details" style={{background:"none",border:"none",color:t.sub,cursor:"pointer",fontSize:16,padding:"0 2px"}}>✕</button></div><div style={{fontSize:12.5,color:t.sub,lineHeight:1.6}}>{selSec.detail}</div></div>:<div style={{fontSize:10.5,color:t.sub,textAlign:"center",marginBottom:10,opacity:0.6}}>No sector selected — tap a pin above</div>}<Note t={t} color="#5b8ec8">📏 <strong style={{color:t.text}}>Rate of advance:</strong> ISW assessed Russian forces gained 37.85 km² in July 2026 — an area smaller than Manhattan, averaging 1.22 km² per day — and described the rate as remaining low two and a half months into the Spring-Summer 2026 offensive, which has produced no operationally significant gains. Read the sector statuses below against that baseline: “ACTIVE” and “CRITICAL” describe intensity of fighting, not territorial change.</Note><ST t={t}>🎯 Sector Analysis</ST>{SECTORS.map(s=><Card key={s.name} t={t} style={{borderLeft:`4px solid ${s.color}`,cursor:"pointer"}} onClick={()=>setSel(sel===s.name?null:s.name)}><div style={{padding:"13px 14px"}}><div style={{display:"flex",alignItems:"center",gap:8}}><span style={{fontSize:18}}>{s.icon}</span><span style={{fontSize:14,fontWeight:700,color:t.text,flex:1}}>{s.name}</span><Pill label={s.status} color={s.color}/><span style={{fontSize:12,color:t.sub}}>{sel===s.name?"▲":"▼"}</span></div>{sel===s.name&&<div style={{fontSize:12.5,color:t.sub,lineHeight:1.6,paddingTop:8}}>{s.detail}</div>}</div></Card>)}</div>;}

const STRIKE_IMPACT_WEEK={weekLabel:"Aug 27 – Sep 2 (partial — through Sep 1)",cities:[
  {name:"Kyiv",x:186.6,y:71.4,hit:true,severity:"critical",note:"Sixth straight night of strikes into Sep 1 — the heaviest of the run. 12 killed, 21+ injured across Kyiv and the oblast: 7 railway workers killed at a depot on the left bank (6 confirmed by Ukrzaliznytsia), an Indian national among the dead. Russia used a large number of jet-powered Banderol drones and ballistic missiles; Ukraine's Air Force intercepted 5 ballistic missiles."},
  {name:"Kyiv Oblast (Boryspil/Brovary)",x:196.0,y:78.0,hit:true,severity:"critical",note:"A missile struck a five-story residential building in Boryspil overnight into Sep 1, killing 4 and injuring 13; 48–50 residents evacuated. A separate strike in Brovary killed 4 and injured 13 more, 8 in a damaged apartment building."},
  {name:"Odesa",x:190.8,y:199.2,hit:true,severity:"major",note:"Guided bomb and drone strikes continued into Sep 1, damaging residential buildings and a sewing workshop (1 injured), and hitting the Orlivka ferry crossing on the Romanian border, suspending its operation. Thousands of households left without power."},
  {name:"Zaporizhzhia",x:285.8,y:155.4,hit:true,severity:"major",note:"Aug 25: struck twice in one morning — a guided aerial bomb hit the regional center killing 2, while a separate drone strike hit a parking lot injuring 7. Aug 28: a drone strike on an Epicentr hypermarket wounded 4."},
  {name:"Kherson",x:245.4,y:186.9,hit:true,severity:"critical",note:"Overnight Aug 27–28: the city's combined heat and power plant was struck by 4 guided aerial bombs, destroying all remaining generating equipment per Naftogaz — leaving the plant fully inoperable ahead of autumn."},
  {name:"Dnipro",x:283.6,y:135.4,hit:false},
  {name:"Kharkiv",x:309.2,y:86.2,hit:true,severity:"minor",note:"Named among the primary targets of the Sep 1 barrage alongside Kyiv and Odesa oblasts, per Ukraine's Air Force; a death was reported in the northern Kharkiv region earlier in the week."},
  {name:"Luhansk",x:375.3,y:131.9,hit:false},
  {name:"Donetsk",x:342.9,y:149.6,hit:false},
]};
function StrikeImpactMap({t,data}){
  const[sel,setSel]=useState(null);
  const selCity=sel?data.cities.find(c=>c.name===sel):null;
  return <div>
  <div style={{borderRadius:12,overflow:"hidden",border:"1px solid rgba(59,130,246,0.2)",marginBottom:sel?0:8}}>
    <svg viewBox="0 0 400 279" width="100%" style={{display:"block",background:"#0a1524"}}>
      <path d={UA_LAND_PATH} fill="#1e3a5f" stroke="#2d5f99" strokeWidth="1.2"/>
      <path d={UA_CRIMEA_PATH} fill="#1e3a5f" stroke="#2d5f99" strokeWidth="1.2"/>
      <path d={UA_OCCUPIED_PATH} fill="#4a1111" stroke="#8b2222" strokeWidth="1" opacity="0.85"/>
      {data.cities.map(c=><g key={c.name} style={{cursor:c.hit?"pointer":"default"}} onClick={()=>c.hit&&setSel(sel===c.name?null:c.name)}>
        {c.hit&&<circle cx={c.x} cy={c.y} r="13" fill={sevColor(c.severity)} opacity="0.18" style={{transformOrigin:`${c.x}px ${c.y}px`,animation:"svgPulse 2.2s ease-in-out infinite"}}/>}
        {c.hit&&sel===c.name&&<circle cx={c.x} cy={c.y} r="16" fill="none" stroke={sevColor(c.severity)} strokeWidth="1.5" opacity="0.9" strokeDasharray="3,2"/>}
        <circle cx={c.x} cy={c.y} r={c.hit?7:3} fill={c.hit?sevColor(c.severity):"#60a5fa"} opacity={c.hit?1:0.6} stroke="#0c1829" strokeWidth={c.hit?1.5:1}/>
        <text x={c.x+8} y={c.y+4} fontSize={c.hit?8:7} fill={c.hit?sevColor(c.severity):"#7a93b8"} fontWeight={c.hit?"bold":"normal"} opacity="0.9">{c.name}</text>
      </g>)}
      <rect x="0" y="263" width="400" height="16" fill="rgba(0,0,0,0.65)"/>
      <text x="8" y="274" fontSize="8" fill="#94a3b8">Week of {data.weekLabel} — filled = confirmed strike, sized by severity, tap for detail</text>
    </svg>
  </div>
  {selCity&&<div style={{marginBottom:8,background:`${sevColor(selCity.severity)}12`,border:`1.5px solid ${sevColor(selCity.severity)}55`,borderRadius:10,padding:"12px 14px"}}><div style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}><span style={{fontSize:13,fontWeight:800,color:t.text,flex:1}}>{selCity.name}</span><span style={{fontSize:9,fontWeight:700,color:sevColor(selCity.severity),background:sevColor(selCity.severity)+"22",borderRadius:10,padding:"1px 7px",textTransform:"uppercase"}}>{selCity.severity}</span><button onClick={()=>setSel(null)} aria-label="Close details" style={{background:"none",border:"none",color:t.sub,cursor:"pointer",fontSize:14,padding:"0 2px"}}>✕</button></div><div style={{fontSize:12,color:t.sub,lineHeight:1.6}}>{selCity.note}</div></div>}
  {!selCity&&<div style={{fontSize:10.5,color:t.sub,textAlign:"center",marginBottom:8,opacity:0.6}}>Tap a highlighted city for strike detail</div>}
  </div>;
}
function AirDefTab({t}){return <div>
      <Hero t={t} color="#06b6d4"><div style={{fontSize:11,fontWeight:800,letterSpacing:".12em",color:"#67e8f9",marginBottom:6}}>🛡️ AIR DEFENSE — THE INTERCEPT WAR</div><div style={{fontSize:12,color:"rgba(255,255,255,.65)",lineHeight:1.6}}>Ukraine wins the drone fight on economics and loses the ballistic fight on inventory. A brief late-July recovery (up to 71% on Jul 25-26) reversed hard in August: 1 of 27 intercepted Aug 1 in Kyiv, 0 of 24 nationwide on Aug 5. The gap was never skill — it is PAC-3 stock, and Zelensky says allies have delivered only a third of 2026's planned air-defense missiles versus 2025. On Jul 8 at Ankara, Trump licensed Ukraine to manufacture Patriots itself; no timeline yet exists.</div></Hero>
      <Grid2 t={t} items={[
        {icon:"🎯",label:"Drone intercept rate",val:"91.7%",sub:"May 2026 monthly avg; ~89% on Jul 4 night",color:"#22c55e"},
        {icon:"💰",label:"Interceptor economics",val:"$7.5k vs $35k",sub:"UA interceptor drone vs Shahed/Geran — cost flipped",color:"#5b8ec8"},
        {icon:"🚀",label:"Ballistic intercepts",val:"Data withheld",sub:"UA AF stopped publishing intercept counts Aug 8 (shortage-driven, per FT); Zelensky says Ukraine has ~1% of US Patriot stockpile, needs 5% for winter, 10% to stop all ballistic attacks.",color:"#dc2626"},
        {icon:"📜",label:"Patriot license",val:"Contested",sub:"Jul 31 walk-back stands; The Atlantic (Aug 9): Raytheon/Lockheed resisting license over IP and cost-competition concerns, not just security.",color:"#dc2626"},
      ]}/>
      <ST t={t} color="#06b6d4">🗺️ This Week's Impact Map</ST>
      <StrikeImpactMap t={t} data={STRIKE_IMPACT_WEEK}/>
      <div style={{fontSize:10.5,color:t.sub,lineHeight:1.5,marginBottom:12,paddingLeft:2}}>Shows confirmed large-scale strikes on major Ukrainian cities this week only — not every reported incident. Ballistic intercept rate trend (June–present) moved to Ukraine Overview.</div>
      <ST t={t} color="#06b6d4">📋 The Layered System</ST>
      <Card t={t}><div style={{padding:"11px 14px"}}><div style={{fontSize:12,color:t.sub,lineHeight:1.7}}>
        <div style={{marginBottom:6}}><span style={{color:t.text,fontWeight:700}}>The Jul 8 shift — a license, not a delivery</span> — Trump: "We're going to give a license to you to make Patriots... I said, make them yourself." Zelensky, Jul 9: the licence is agreed "at the political level," with interceptor supplies due "in the coming days" — but an adviser to the defence minister warns setting up production will take many months, and reported bottlenecks run 12-24 months on subcontracted components. Trump had not yet informed Lockheed Martin or RTX. Kyiv has meanwhile asked nearly 40 countries for interceptors from existing stocks, against future contracted deliveries. Separately, Poland and several NATO states signed on to a European PAC-3 maintenance center and Polish co-production with Ukraine; Poland is sending 5 missiles now. Ukraine's own 'Freyja' anti-ballistic interceptor may draw eight European partners.</div>
        <div style={{marginBottom:6}}><span style={{color:t.text,fontWeight:700}}>Top layer — Patriot/SAMP-T</span> — The only counter to Iskander-M and Zircon-class threats. Stock is the war's binding constraint: US production ~500-650 PAC-3 MSE/yr against global demand, European GEM-T co-production (up to 1,000 missiles, DE/NL/RO/ES) the structural fix. Zelensky renewed interceptor appeals after the Kyiv strike.</div>
        <div style={{marginBottom:6}}><span style={{color:t.text,fontWeight:700}}>Middle layer — IRIS-T, NASAMS, F-16s</span> — Cruise-missile and heavy-drone attrition; Denmark-donated F-16s now fly regular intercept sorties. Effective but missile-hungry against saturation raids.</div>
        <div style={{marginBottom:6}}><span style={{color:t.text,fontWeight:700}}>Bottom layer — interceptor drones + mobile teams</span> — The 2026 revolution: $7.5k interceptor drones and gun trucks now take the bulk of Shahed/Gerbera kills, flipping the exchange ratio Ukraine's way and freeing missiles for what only missiles can stop. Sky Fortress acoustic net cues the layer.</div>
        <div><span style={{color:t.text,fontWeight:700}}>The stress test</span> — Saturation raids mix decoys (Gerbera), jet drones (Geran-4), cruise and ballistic in one wave to exhaust the stack top-down. The Jul 1-2 raid is the worst-case validation of this pattern.</div>
      </div></div></Card>
          </div>;}

