const LEV_POI=[
  {n:"Tel Aviv",lat:32.085,lon:34.782,k:"isr",x:"Israel's commercial capital and largest metropolitan area. A primary target set for long-range rocket and drone fire from multiple directions, and the country's main air-defense priority after Jerusalem."},
  {n:"Jerusalem",lat:31.768,lon:35.214,k:"isr",x:"Seat of Israeli government. Its status — particularly the Old City and holy sites — remains one of the core unresolved issues in every negotiating framework."},
  {n:"Haifa",lat:32.794,lon:34.990,k:"isr",x:"Israel's largest port and main petrochemical hub, roughly 30km from the Lebanese border. Its proximity to Hezbollah rocket range makes it the most exposed strategic-industrial target in the north."},
  {n:"Ashkelon",lat:31.669,lon:34.571,k:"isr",x:"Coastal city roughly 13km north of the Gaza Strip. Hosts a major power station and the terminus of a strategic oil pipeline; routinely within short-range rocket fire from Gaza."},
  {n:"Gaza City",lat:31.502,lon:34.467,k:"gaza",x:"The largest city in the Gaza Strip and the territory's administrative center. Its hospital system has been described by the UN as collapsed."},
  {n:"Khan Younis",lat:31.340,lon:34.306,k:"gaza",x:"Second-largest city in the Gaza Strip, in the southern half of the territory. Repeatedly a focus of ground operations and mass displacement."},
  {n:"Rafah Crossing",lat:31.247,lon:34.266,k:"gaza",x:"The only Gaza crossing not directly bordering Israel, connecting the Strip to Egypt's Sinai. The primary route for aid entry and the main pressure point in every aid-access dispute."},
  {n:"Beirut",lat:33.85,lon:35.58,k:"lbn",x:"Lebanon's capital. The southern suburbs (Dahiyeh) are Hezbollah's political and command center, making the city a recurring target set distinct from the border zone."},
  {n:"Sidon",lat:33.563,lon:35.369,k:"lbn",x:"Coastal city and Lebanon's third largest, between Beirut and the Litani. A logistical waypoint on the main north-south coastal corridor."},
  {n:"Tyre",lat:33.271,lon:35.196,k:"lbn",x:"Southern Lebanese port city below the Litani River, inside the zone Israel says it will hold until Hezbollah disarms. Among the most heavily contested areas of the ceasefire dispute."},
  {n:"Beqaa Valley",lat:33.85,lon:35.95,k:"lbn",x:"Lebanon's main agricultural valley between two mountain ranges, running toward the Syrian border. Long identified as a Hezbollah logistics and resupply corridor."},
  {n:"Damascus",lat:33.514,lon:36.277,k:"syr",x:"Syria's capital. Historically the primary transit node for Iranian materiel moving toward Lebanon — the land route that made Syria strategically central to the wider conflict."},
  {n:"Golan Heights",lat:33.00,lon:35.75,k:"syr",x:"Plateau captured by Israel in 1967 and annexed in 1981; the annexation is not internationally recognized. Its elevation overlooks both northern Israel and southwestern Syria."},
  {n:"Quneitra",lat:33.126,lon:35.824,k:"syr",x:"Syrian town beside the Golan demarcation line, adjacent to the UN-patrolled separation zone (UNDOF). A sensitive indicator point for Israeli-Syrian escalation."},
  {n:"Amman",lat:31.945,lon:35.928,k:"jor",x:"Jordan's capital. Jordan hosts a large Palestinian population and sits on the main overflight corridor between Iraq/Iran and Israel, making its airspace strategically consequential."},
];
