const AM_POI={
  mexico:[
    {n:"Mexico City",lat:19.4326,lon:-99.1332,x:"Mexico's capital and the seat of the federal government leading the security response to cartel violence. Also the base for national homicide and displacement reporting cited across this theater."},
    {n:"Culiacán",lat:24.8091,lon:-107.3940,x:"Capital of Sinaloa state and the historic stronghold of the Sinaloa Cartel. The city has seen repeated waves of cartel-faction violence, including major clashes following the 2024 arrest and alleged betrayal of cartel leadership."},
    {n:"Guadalajara",lat:20.6597,lon:-103.3496,x:"Capital of Jalisco state and the commercial heart of CJNG territory. Mexican forces killed CJNG leader Nemesio 'El Mencho' Oseguera Cervantes in Jalisco on Feb 22, 2026, triggering blockades and clashes across a dozen states."},
    {n:"Tijuana",lat:32.5149,lon:-117.0382,x:"Border city opposite San Diego and one of Mexico's most violent, driven by competition between Sinaloa and CJNG factions for control of the smuggling corridor into the US."},
    {n:"Ciudad Juárez",lat:31.6904,lon:-106.4245,x:"Border city opposite El Paso, Texas. Historically one of the deadliest cities in the Western Hemisphere during peak cartel-war years, and still a key smuggling corridor and displacement flashpoint."},
  ],
  cuba:[
    {n:"Havana",lat:23.113,lon:-82.366,x:"Cuba's capital and largest city. Repeatedly hit by the island-wide grid collapses that have defined 2026 — roughly 10 million people affected each time the national system fails."},
    {n:"Matanzas",lat:23.041,lon:-81.575,x:"Site of Cuba's main oil storage and supertanker terminal. Central to fuel import and distribution, and therefore the primary pressure point of the oil blockade."},
    {n:"Santiago de Cuba",lat:20.021,lon:-75.829,x:"Cuba's second city, in the southeast. Distance from Havana makes it especially exposed when national fuel distribution breaks down."},
    {n:"Guantanamo Bay",lat:19.902,lon:-75.148,x:"US naval station held under a 1903 lease, the only US military installation on Cuban soil. Operates independently of the Cuban state and is unaffected by the blockade."},
  ],
  venezuela:[
    {n:"Caracas",lat:10.491,lon:-66.902,x:"Venezuela's capital. Target of Operation Absolute Resolve on Jan 3, 2026, when roughly 200 US special operations forces captured Nicolas Maduro in an operation lasting about 2 hours 20 minutes."},
    {n:"Maracaibo",lat:10.654,lon:-71.64,x:"Center of Venezuela's oil industry, beside Lake Maracaibo. The country's petroleum heartland and the source of the crude that had been Cuba's fuel lifeline."},
    {n:"Puerto Cabello",lat:10.473,lon:-68.012,x:"Venezuela's principal commercial port and site of a major refinery complex. A focal point for the tanker seizures that began in December 2025."},
    {n:"Valencia",lat:10.162,lon:-68.003,x:"Venezuela's third-largest city and main industrial center, inland from Puerto Cabello."},
  ],
  haiti:[
    {n:"Port-au-Prince",lat:18.541,lon:-72.336,x:"Haiti's capital. Gang coalitions control an estimated 70-90% of the metropolitan area, including the routes in and out, leaving the state with limited effective authority."},
    {n:"Cite Soleil",lat:18.577,lon:-72.335,x:"Densely populated district of Port-au-Prince and a center of gang control. Repeated site of mass-casualty clashes and displacement waves through 2026."},
    {n:"Gonaives",lat:19.451,lon:-72.689,x:"Principal city of the Artibonite department, north of the capital. Gangs expanded into Artibonite and Centre over the past year, extending the crisis beyond Port-au-Prince."},
    {n:"Cap-Haitien",lat:19.759,lon:-72.198,x:"Haiti's second city, on the north coast. Historically less affected than the capital, making it a critical remaining port and access point."},
    {n:"Santo Domingo",lat:18.486,lon:-69.931,x:"Capital of the Dominican Republic, which shares Hispaniola with Haiti. The land border is the main route for Haitians fleeing the crisis and a persistent bilateral flashpoint."},
  ],
  colombia:[
    {n:"Bogota",lat:4.711,lon:-74.072,x:"Colombia's capital. Seat of the Petro government, which suspended ELN peace talks and invoked emergency powers after the January 2025 Catatumbo offensive."},
    {n:"Cucuta",lat:7.894,lon:-72.504,x:"Main city on the Venezuelan border and the primary reception point for people displaced from Catatumbo. Also the site of protests after Maduro's capture."},
    {n:"Tibu",lat:8.64,lon:-72.735,x:"Municipality at the heart of the Catatumbo conflict zone. Among the areas worst affected by the ELN offensive against FARC dissidents of the 33rd Front."},
    {n:"Medellin",lat:6.244,lon:-75.581,x:"Colombia's second city. A center of the country's long conflict with armed groups and drug trafficking organizations."},
  ],
};

function AmericasCountryMap({t,country}){
  const cfg=AM_MAPS[country];
  const pois=AM_POI[country]||[];
  const[sel,setSel]=useState(null);
  const sea=t.isDark?"#08131f":"#dbeafe";
  const land=t.isDark?"#16212e":"#e2e8f0";
  const edge=t.isDark?"#2c3c4f":"#94a3b8";
  if(!cfg) return null;
  const X=(lon)=>((lon-cfg.lon0)/(cfg.lon1-cfg.lon0))*cfg.W;
  const Y=(lat)=>((cfg.lat1-lat)/(cfg.lat1-cfg.lat0))*cfg.H;
  return <Card t={t} style={{padding:"12px 8px 8px"}}>
    <div style={{padding:"0 8px 8px",display:"flex",alignItems:"baseline",justifyContent:"space-between",flexWrap:"wrap",gap:4}}>
      <div style={{fontSize:12,fontWeight:700,color:t.text}}>{cfg.title} — Geographic Reference</div>
      <div style={{fontSize:10,color:t.sub}}>to scale · tap any point</div>
    </div>
    <div style={{width:"100%",overflow:"hidden",borderRadius:10}}>
    <svg viewBox={`0 0 ${cfg.W} ${cfg.H}`} style={{width:"100%",height:"auto",display:"block",background:sea}} role="img" aria-label={`Interactive map of ${cfg.title} showing major cities and strategic points of interest.`}>
      {cfg.codes.map(code=><path key={code} d={AM_PATHS[`${country}_${code}`]} fill={land} stroke={edge} strokeWidth="1"/>)}
      {pois.map((o,idx)=>{
        const isSel=sel===idx;
        const x=X(o.lon),y=Y(o.lat);
        const flip=x>cfg.W-72;
        return <g key={o.n} tabIndex={0} role="button" aria-label={o.n} style={{cursor:"pointer"}} onClick={()=>setSel(idx)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();setSel(idx);}}}>
          <circle cx={x} cy={y} r="10" fill="transparent"/>
          {isSel&&<circle cx={x} cy={y} r="7.5" fill="none" stroke={cfg.accent} strokeWidth="1.2" opacity=".55"/>}
          <circle cx={x} cy={y} r={isSel?4.4:3.2} fill={cfg.accent} stroke={sea} strokeWidth="0.8" style={{transition:"r .2s ease"}}/>
          <text x={flip?x-6:x+6} y={y+3} textAnchor={flip?"end":"start"} fill={t.text} fontSize="8" fontWeight={isSel?800:600} fontFamily={FONT} style={{pointerEvents:"none",paintOrder:"stroke"}} stroke={sea} strokeWidth="2.2" strokeLinejoin="round">{o.n}</text>
        </g>;
      })}
    </svg>
    </div>
    <div style={{margin:"10px 8px 0",padding:"11px 12px",background:t.isDark?"#0b1420":"#f1f5f9",borderRadius:8,border:`1px solid ${t.border}`,minHeight:64}}>
      {sel===null&&<div style={{fontSize:11,color:t.sub,fontStyle:"italic"}}>No location selected. Tap a marker on the map above.</div>}
      {sel!==null&&(()=>{const o=pois[sel];return <>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:5,flexWrap:"wrap",gap:6}}>
          <span style={{fontSize:9,fontWeight:700,color:cfg.accent,textTransform:"uppercase",letterSpacing:".06em"}}>{cfg.title}</span>
          <span style={{fontSize:8.5,color:t.sub,fontFamily:"monospace"}}>{Math.abs(o.lat).toFixed(2)}°{o.lat>=0?"N":"S"}   {Math.abs(o.lon).toFixed(2)}°{o.lon>=0?"E":"W"}</span>
        </div>
        <div style={{fontSize:13,fontWeight:700,color:t.text,marginBottom:5}}>{o.n}</div>
        <div style={{fontSize:11.5,color:t.sub,lineHeight:1.6}}>{o.x}</div>
      </>;})()}
    </div>
    <div style={{padding:"6px 8px 0",fontSize:9.5,color:t.sub,opacity:.7}}>{cfg.note}</div>
  </Card>;
}

