function CrimeaBlackSeaMap({t,mode}){
  const sea=t.isDark?"#08131f":"#dbeafe";
  const land=t.isDark?"#16212e":"#e2e8f0";
  const edge=t.isDark?"#2c3c4f":"#94a3b8";
  const[sel,setSel]=useState(null);
  const KIND={disabled:"#dc2626",destroyed:"#7f1d1d",damaged:"#f97316",contested:"#eab308",sunk:"#5b8ec8",land:"#94a3b8"};
  const pois=CBS_POI[mode]||[];
  const accent=mode==="crimea"?"#ef4444":"#06b6d4";
  const title=mode==="crimea"?"Crimea \u2014 Supply Routes":"Northern Black Sea \u2014 Fleet Losses";
  const X=(lon)=>((lon-CBS_MAP.lon0)/(CBS_MAP.lon1-CBS_MAP.lon0))*CBS_MAP.W;
  const Y=(lat)=>((CBS_MAP.lat1-lat)/(CBS_MAP.lat1-CBS_MAP.lat0))*CBS_MAP.H;
  return <Card t={t} style={{padding:"12px 8px 8px"}}>
    <div style={{padding:"0 8px 8px",display:"flex",alignItems:"baseline",justifyContent:"space-between",flexWrap:"wrap",gap:4}}>
      <div style={{fontSize:12,fontWeight:700,color:t.text}}>{title}</div>
      <div style={{fontSize:10,color:t.sub}}>tap any point</div>
    </div>
    <div style={{width:"100%",overflow:"hidden",borderRadius:10}}>
    <svg viewBox={`0 0 ${CBS_MAP.W} ${CBS_MAP.H}`} style={{width:"100%",height:"auto",display:"block",background:sea}} role="img" aria-label={`Map of ${title} showing key points of interest.`}>
      <path d={CRIMEA_OUTLINE} fill={land} stroke={edge} strokeWidth="1"/>
      {CBS_LAND.map(c=><circle key={c.n} cx={X(c.lon)} cy={Y(c.lat)} r="1.6" fill={edge} opacity="0.7"/>)}
      {pois.map((o,idx)=>{
        const isSel=sel===idx;
        const col=KIND[o.k]||accent;
        const x=X(o.lon),y=Y(o.lat);
        const lx=o.lx??6, ly=o.ly??3, an=o.an??"start";
        return <g key={o.n} tabIndex={0} role="button" aria-label={o.n} style={{cursor:"pointer"}} onClick={()=>setSel(idx)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();setSel(idx);}}}>
          <circle cx={x} cy={y} r="9" fill="transparent"/>
          {isSel&&<circle cx={x} cy={y} r="7" fill="none" stroke={col} strokeWidth="1.2" opacity=".55"/>}
          <circle cx={x} cy={y} r={isSel?4.2:3} fill={col} stroke={sea} strokeWidth="0.8" style={{transition:"r .2s ease"}}/>
          <text x={x+lx} y={y+ly} textAnchor={an} fill={isSel?t.text:t.sub} fontSize="7.5" fontWeight={isSel?800:600} fontFamily={FONT} style={{pointerEvents:"none",paintOrder:"stroke"}} stroke={sea} strokeWidth="2.4" strokeLinejoin="round">{o.n}</text>
        </g>;
      })}
    </svg>
    </div>
    <div style={{margin:"10px 8px 0",padding:"11px 12px",background:t.isDark?"#0b1420":"#f1f5f9",borderRadius:8,border:`1px solid ${t.border}`,minHeight:64}}>
      {sel===null&&<div style={{fontSize:11,color:t.sub,fontStyle:"italic"}}>No location selected. Tap a marker on the map above.</div>}
      {sel!==null&&(()=>{const o=pois[sel];const col=KIND[o.k]||accent;return <>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:5,flexWrap:"wrap",gap:6}}>
          <span style={{fontSize:9,fontWeight:700,color:col,textTransform:"uppercase",letterSpacing:".06em"}}>{o.k}</span>
          <span style={{fontSize:8.5,color:t.sub,fontFamily:"monospace"}}>{o.lat.toFixed(2)}°N   {o.lon.toFixed(2)}°E</span>
        </div>
        <div style={{fontSize:13,fontWeight:700,color:t.text,marginBottom:5}}>{o.n}</div>
        <div style={{fontSize:11.5,color:t.sub,lineHeight:1.6}}>{o.x}</div>
      </>;})()}
    </div>
    <div style={{padding:"6px 8px 0",fontSize:9.5,color:t.sub,opacity:.7}}>Crimea coastline plotted from real OpenStreetMap-derived boundary data (world-geojson, GPL-3.0). A few naval-strike locations are marked approximate where sources didn't give precise coordinates.</div>
  </Card>;
}

